/**
 * The Fall of Jerusalem
 * ---------------------
 * The city falls after a long siege; the king's sons are slain, the temple is burned, and the people are taken into exile. Stage: smoke over the city, a wall breached, a king fleeing by night, a fire on the temple hill; the last light of a long night.
 *
 * Palette 0x241a10 → 0x060402 · light: ember · hero: fire
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jeremiah-kit.js.
 */

import { THREE, createScene, cityGate, house, temple, column, oak, flame, person, crowd } from './jeremiah-kit.js';

const BG = 0x241a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2982336970, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hills: angular ridges on the horizon */
    const hills = W.grp(group, [0, 0, 0], { name: 'hills' });
    for (let i = 0; i < 9; i++) {
        const x = -130 + i * 32 + W.rr(-8, 8);
        W.add(hills, W.G('cone', W.rr(14, 28), W.rr(10, 24), 5), W.mat(0x050302), [x, 0, -95 - W.rr(0, 25)], { r: [0, W.r() * 3, 0] });
    }
    W.backdrop(hills);

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-17, 0, -58], { name: 'city', r: [0, -0.15, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* temple: colonnade and glowing doorway */
    const templeG = W.grp(group, [0, 0, -46], { name: 'temple', r: [0, -0.13, 0] });
    temple(W, templeG, 0, 0, 0, 1.1, { stone: 0x070402, trim: 0x19120b });
    W.backdrop(templeG);

    /* hero: the burning bush */
    oak(W, group, 0, 0, 0, 0.75, { leaf: 0x3a4a20, leaf2: 0x4a5a28 });
    flame(W, group, 0, 1.4, 0, 1.0);
    W.point(0xff8a30, 2.4, 60, 0, 3, 0, 0.4);
    W.disc([0, 6, -12], 7, 0xffa050, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.25, s: 1.13 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 17, 70, 44, [0x241a10, 0x060402, 0x8a6a44, 0x6a4a30, 0xc8b088, 0x5a4a6a]);

    return W.finish();
}

export default { build };
